# ---- Packages -------------------------------------------------------------

library(shiny)
library(ggplot2)
library(grid)
library(gridExtra)
library(readxl)

if (FALSE) {
  library(munsell)
}

# Bundled metadata

metadata  <- readRDS("metadata.rds")
countries <- readRDS("countries.rds")

metadata$QuestionCode <- trimws(as.character(metadata$QuestionCode))
metadata$AnswerCode   <- trimws(as.character(metadata$AnswerCode))
countries$Code        <- trimws(as.character(countries$Code))

lookup_meaning <- function(md, code){
  code <- trimws(as.character(code))
  hit <- md$Meaning[md$AnswerCode == code]
  if (length(hit) == 0) NA_character_ else hit[1]
}

# Plotting / table-building functions 

discrete_exclusive <- function(d, md){
  d <- d[, c(1, 2)]
  d <- d[which(d[, 2] != "-oth-"), ]
  colnames(d) <- c("id", "a")
  d <- d[!is.na(d$a), ]
  title <- md$Question[1]
  d$afull <- sapply(d$a, function(x) lookup_meaning(md, x))
  ggplot() +
    geom_bar(data = d, aes(x = afull), col = "black", fill = "lightblue") +
    xlab(NULL) + ylab(NULL) + ggtitle(NULL) +
    coord_flip() +
    theme_bw() +
    theme(
      panel.grid.major.y = element_blank(),
      panel.grid.minor.x = element_blank(),
      axis.ticks = element_blank()
    )
}

continuous <- function(d, md){
  colnames(d) <- c("id", "a")
  d <- d[!is.na(d$a), ]
  title <- md$Question[1]
  xbreaks <- round(as.numeric(quantile(d$a, probs = c(0, .25, .5, .75, 1))))
  ggplot() +
    geom_histogram(
      data = d, aes(x = a),
      col = "black", fill = "#b3de69", bins = 15, alpha = .7
    ) +
    geom_boxplot(
      data = d, aes(x = a, y = 1.5),
      fill = NA, width = 2, col = "red"
    ) +
    scale_x_continuous(breaks = xbreaks) +
    xlab(NULL) + ylab(NULL) + ggtitle(NULL) +
    theme_bw() +
    theme(
      axis.text.y = element_blank(),
      panel.grid.major.y = element_blank(),
      panel.grid.minor.x = element_blank(),
      panel.grid.minor.y = element_blank(),
      axis.ticks = element_blank()
    )
}

discrete_inclusive <- function(d, md, q){
  n_ans <- ncol(d) - 1
  mist <- rowSums(is.na(d))
  d <- d[which(mist != n_ans), ]
  answers <- sapply(colnames(d), function(x) strsplit(x, "\\.")[[1]][2])
  answers <- as.character(answers)
  answers <- tail(answers, -1)
  answers <- head(answers, -1)
  pdat <- data.frame(a = answers)
  pdat$afull <- sapply(pdat$a, function(x) lookup_meaning(md, x))
  pdat$num <- NA
  for (i in 1:nrow(pdat)) {
    ansheet <- d[, paste0(q, ".", pdat$a[i], ".")]
    pdat$num[i] <- sum(ansheet == "Y", na.rm = TRUE)
  }
  pdat$prop <- pdat$num / nrow(d)
  title <- md$Question[1]
  pdat$afull <- factor(pdat$afull, levels = rev(pdat$afull))
  ggplot() +
    geom_bar(
      data = pdat, aes(x = prop, y = afull),
      fill = "orange", col = "black", stat = "identity"
    ) +
    scale_x_continuous(
      limits = c(0, 1),
      breaks = c(0, .2, .4, .6, .8, 1),
      labels = paste0(100 * c(0, .2, .4, .6, .8, 1), "%")
    ) +
    ggtitle(NULL) + ylab(NULL) + xlab(NULL) +
    theme_bw() +
    theme(
      axis.ticks = element_blank(),
      panel.grid.major.y = element_blank(),
      panel.grid.minor.x = element_blank()
    )
}

ranking <- function(d, md){
  n_ans <- ncol(d) - 1
  mist <- rowSums(is.na(d))
  d <- d[which(mist != n_ans), ]
  answers <- sapply(colnames(d), function(x) strsplit(x, "\\.")[[1]][2])
  answers <- as.character(answers)
  answers <- tail(answers, -1)
  answers <- paste0("A", answers)
  pdat <- data.frame()
  for (i in 1:n_ans) {
    out <- table(d[, i + 1])
    pdat <- rbind(
      pdat,
      data.frame(a = names(out), rank = i, val = as.numeric(out))
    )
  }
  pdat$afull <- sapply(pdat$a, function(x) lookup_meaning(md, x))
  pdat$prop <- pdat$val / nrow(d)
  title <- md$Question[1]
  pdat$afull <- factor(pdat$afull, levels = rev(md$Meaning))
  pdat$rank <- paste0("Ranked as #", as.character(pdat$rank))
  pdat$rank <- factor(pdat$rank, levels = rev(unique(pdat$rank)))
  scalevals <- c(
    "#8dd3c7", "#ffffb3", "#bebada", "#fb8072", "#80b1d3", "#fdb462"
  )[1:n_ans]
  names(scalevals) <- md$Meaning
  ggplot() +
    geom_bar(
      data = pdat, aes(x = prop, y = rank, group = afull, fill = afull),
      col = "black", stat = "identity"
    ) +
    scale_x_continuous(
      limits = c(0, 1),
      breaks = c(0, .2, .4, .6, .8, 1),
      labels = paste0(100 * c(0, .2, .4, .6, .8, 1), "%")
    ) +
    scale_fill_manual(values = scalevals) +
    ggtitle(NULL) + ylab(NULL) + xlab(NULL) +
    theme_bw() +
    theme(
      axis.ticks = element_blank(),
      panel.grid.major.y = element_blank(),
      panel.grid.minor.x = element_blank(),
      legend.title = element_blank(),
      legend.position = "bottom"
    )
}

country_table <- function(d, countries){
  pdat <- data.frame(table(d[, 2]))
  pdat$country <- countries$Country[match(trimws(as.character(pdat$Var1)), countries$Code)]
  pdat <- pdat[rev(order(pdat$Freq)), ]
  pdat$country <- factor(pdat$country, levels = rev(pdat$country))
  pdat <- pdat[, c("country", "Freq")]
  colnames(pdat) <- c("Country", "Number of responses")
  list(grob = tableGrob(pdat, rows = NULL), n = nrow(pdat))
}

# Build the full report as a list of items 

build_report <- function(data, metadata, countries, only_full_responses){
  dcols <- colnames(data)
  if (!"G10Q01" %in% dcols) {
    stop("This doesn't look like a survey export - couldn't find the expected 'G10Q01' column.")
  }
  lastq <- which(dcols == "G10Q01")

  if (only_full_responses) {
    if (!"submitdate" %in% dcols) {
      stop("Can't filter to full responses - no 'submitdate' column in this file.")
    }
    data <- data[!is.na(data$submitdate), ]
  }
  if (nrow(data) == 0) {
    stop("No responses left after filtering.")
  }

  questions <- unique(metadata$QuestionCode)
  questions <- questions[!is.na(questions)]

  items <- list()

  for (q in questions) {
    qcols <- grep(q, dcols)
    qcols <- qcols[qcols <= lastq]
    if (length(qcols) == 0) next
    d <- data[, c(1, qcols), drop = FALSE]
    md <- metadata[metadata$QuestionCode == q, ]
    if (nrow(md) == 0) next
    qtype <- md$Type[1]

    # Wrapped per-question: if one question's data doesn't match what the
    # metadata expects, that question shows its own error message instead
    # of taking down the whole report - much easier to debug.
    item <- tryCatch(
      switch(
        qtype,
        "DiscreteExclusive" = list(
          type = "plot", obj = discrete_exclusive(d, md),
          title = md$Question[1], height = 260
        ),
        "DiscreteInclusive" = list(
          type = "plot", obj = discrete_inclusive(d, md, q),
          title = md$Question[1], height = 260
        ),
        "Continuous" = list(
          type = "plot", obj = continuous(d, md),
          title = md$Question[1], height = 220
        ),
        "Ranking" = list(
          type = "plot", obj = ranking(d, md),
          title = md$Question[1], height = 300
        ),
        "Country" = {
          ct <- country_table(d, countries)
          list(
            type = "table", obj = ct$grob,
            title = md$Question[1], height = max(220, 22 * ct$n + 40)
          )
        },
        NULL
      ),
      error = function(e) {
        list(
          type = "error",
          obj = NULL,
          title = paste0(q, " (", qtype, ")"),
          message = conditionMessage(e),
          height = 80
        )
      }
    )
    if (!is.null(item)) items[[length(items) + 1]] <- item
  }

  items
}

# UI 

ui <- fluidPage(
  tags$head(tags$style(HTML("
    #shiny-notification-panel {
      width: 1600px;
      font-size: 40px;
    }
    .shiny-notification {
      padding: 16px 18px;
    }
    .shiny-notification .progress {
      height: 22px;
      margin-top: 8px;
    }
  "))),
  titlePanel("Attitudes towards anesthesia for pregnant women: a survey [results]"),
  sidebarLayout(
    sidebarPanel(
      fileInput(
        "survey_file",
        "Drag the survey responses .xlsx here",
        accept = c(".xlsx")
      ),
      actionButton("get_results", "Get results", class = "btn-primary"),
      checkboxInput("full_only", "Full responses only", value = FALSE),
      br(),
      textOutput("status")
    ),
    mainPanel(
      uiOutput("report")
    )
  )
)

#  Server

server <- function(input, output, session) {

  report_items <- reactiveVal(NULL)
  status_msg   <- reactiveVal("")
  render_state <- new.env()
  render_state$prog  <- NULL
  render_state$done  <- 0
  render_state$total <- 0

  plot_res <- 72

  run_analysis <- function() {
    status_msg("")
    req(input$survey_file)

    withProgress(message = "Building report", value = 0, {

      incProgress(0.15, detail = "Reading file...")
      only_full_responses <- isTRUE(input$full_only)

      df <- tryCatch(
        as.data.frame(readxl::read_excel(input$survey_file$datapath, sheet = 1)),
        error = function(e) NULL
      )
      if (is.null(df)) {
        status_msg("Couldn't read that file - please upload a valid .xlsx survey export.")
        report_items(NULL)
        return(invisible(NULL))
      }

      colnames(df) <- make.names(colnames(df), unique = TRUE)

      incProgress(0.35, detail = "Matching questions...")

      items <- tryCatch(
        build_report(df, metadata, countries, only_full_responses),
        error = function(e) {
          status_msg(paste("Error:", conditionMessage(e)))
          NULL
        }
      )

      incProgress(0.5, detail = "Preparing charts...")
      report_items(items)
    })
  }

  observeEvent(input$get_results, run_analysis())

  observeEvent(report_items(), {
    if (!is.null(render_state$prog)) {
      render_state$prog$close()
      render_state$prog <- NULL
    }
    items <- report_items()
    renderable <- if (is.null(items)) list() else Filter(function(x) x$type != "error", items)
    render_state$total <- length(renderable)
    render_state$done  <- 0
    if (render_state$total > 0) {
      render_state$prog <- Progress$new(session, min = 0, max = render_state$total)
      render_state$prog$set(message = "Rendering charts", value = 0)
    }
  }, priority = 1000)

  output$status <- renderText(status_msg())

  output$report <- renderUI({
    items <- report_items()
    if (is.null(items) || length(items) == 0) return(NULL)
    tagList(lapply(seq_along(items), function(i) {
      item <- items[[i]]
      if (item$type == "error") {
        tagList(
          h4(item$title),
          div(
            style = "color: #b00020; border-left: 3px solid #b00020; padding-left: 8px;",
            paste("Couldn't render this question:", item$message)
          )
        )
      } else {
        tagList(
          h4(item$title),
          plotOutput(paste0("plot_", i), height = item$height)
        )
      }
    }))
  })

  observe({
    items <- report_items()
    if (is.null(items)) return(NULL)
    for (i in seq_along(items)) {
      local({
        ii <- i
        item <- items[[ii]]
        if (item$type == "error") return(NULL)
        output[[paste0("plot_", ii)]] <- renderPlot({
          if (item$type == "table") {
            grid.newpage()
            grid.draw(item$obj)
          } else {
            print(item$obj)
          }

          # Real completion tracking: each chart reports in as it finishes.
          render_state$done <- render_state$done + 1
          if (!is.null(render_state$prog)) {
            render_state$prog$inc(1, detail = item$title)
            if (render_state$done >= render_state$total) {
              render_state$prog$close()
              render_state$prog <- NULL
            }
          }
        }, res = plot_res)
      })
    }
  })
}

shinyApp(ui, server)
